  const colors=palette();const [lo,hi]=domain(),{left,right,bottom,top}=dimensions,maxCount=Math.max(...result.histogram.map(b=>b.count)),q=result.quote,medianX=plotX(result.median),marketX=q.status==='ready'?plotX(q.price):null;
  out.innerHTML=`<div class="mc-chart-wrap"><div class="mc-chart-top"><span id="mc-animation-status">Full distribution</span><div class="mc-playback"><button id="mc-skip" hidden>Show full chart</button><button id="mc-play" aria-pressed="false">Replay ↻</button></div></div><div id="mc-chart" class="mc-chart" role="slider" tabindex="0" aria-label="Inspect conditional valuation distribution" aria-valuemin="${lo}" aria-valuemax="${hi}" aria-valuenow="${result.median}" aria-describedby="mc-help"><svg viewBox="0 0 960 420" aria-hidden="true"><defs><linearGradient id="mc-bar-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${colors.signal}" stop-opacity=".96"/><stop offset="1" stop-color="${colors.signal}" stop-opacity=".28"/></linearGradient></defs>${[0,.25,.5,.75,1].map(t=>`<line x1="${left}" x2="${right}" y1="${bottom-(bottom-top)*t}" y2="${bottom-(bottom-top)*t}" stroke="white" stroke-opacity=".08"/>`).join('')}<text x="${left}" y="37" class="mc-svg-note" style="fill:${colors.text}">SHARE OF ACCEPTED SCENARIOS</text>${[.5,1].map(t=>`<text x="${right}" y="${bottom-(bottom-top)*t-9}" text-anchor="end" class="mc-svg-note" style="fill:${colors.text}">${fmt(maxCount/result.accepted*t*100,1)}%</text>`).join('')}<g id="mc-bars">${result.histogram.map((bin,i)=>{const x=result.histogram.length===1?plotX(result.median)-12:plotX(bin.low),width=result.histogram.length===1?24:Math.max(2,plotX(bin.high)-x-3),height=bin.count/maxCount*(bottom-top);return `<rect class="mc-bin" data-bin="${i}" x="${x}" y="${bottom-height}" width="${width}" height="${height}" rx="3" fill="${colors.signal}" fill-opacity=".78"/>`}).join('')}</g><g id="mc-particles"></g><line x1="${medianX}" x2="${medianX}" y1="58" y2="${bottom}" stroke="white" stroke-width="1.5" stroke-dasharray="4 5"/><rect x="${Math.max(left,Math.min(right-74,medianX-37))}" y="42" width="74" height="23" rx="11" fill="white"/><text x="${Math.max(left+37,Math.min(right-37,medianX))}" y="57" text-anchor="middle" class="mc-marker-label" fill="${colors.stage}">P50</text>${q.status==='ready'?`<line x1="${marketX}" x2="${marketX}" y1="80" y2="${bottom}" stroke="${colors.signal}" stroke-width="2"/><circle cx="${marketX}" cy="${bottom}" r="5" fill="${colors.signal}"/>`:''}<line id="mc-inspect-line" x1="${medianX}" x2="${medianX}" y1="72" y2="${bottom}" stroke="white" stroke-opacity=".4"/><circle id="mc-inspect-dot" cx="${medianX}" cy="${bottom}" r="5" fill="white"/>${[0,.25,.5,.75,1].map((p,i)=>`<text x="${left+(right-left)*p}" y="358" text-anchor="${i===0?'start':i===4?'end':'middle'}" class="mc-axis-label ${i===1||i===3?'mc-axis-intermediate':''}" style="fill:${colors.text}">${fmt(lo+(hi-lo)*p,hi<20?1:0)}</text>`).join('')}<text x="480" y="403" text-anchor="middle" class="mc-svg-note" style="fill:${colors.text}">${esc(snapshot.currency)} PER ECONOMIC SHARE</text></svg></div><div id="mc-inspector" class="mc-inspector" aria-live="polite" aria-atomic="true"></div><label class="mc-scrubber-label" for="mc-scrubber">Explore the distribution<input id="mc-scrubber" type="range" min="0" max="1000" step="1" value="500" aria-label="Explore simulated value"></label><p id="mc-help" class="mc-help">Tap or drag to inspect. Arrow keys explore; Home / End select the bounds.</p>${result.zeroEquityCount?`<p class="mc-floor-note">${result.zeroEquityShare>=.5?`${fmt(result.zeroEquityShare*100,1)}% of simulated values are zero; the median is also zero. The inspector includes every tied zero in its percentile.`:`${fmt(result.zeroEquityShare*100,1)}% of accepted scenarios reach the zero common-equity floor.`} Raw negative values are retained in the export; this is not an estimated probability of business failure.</p>`:''}</div>`;find('#mc-summary-content').innerHTML=`<div class="mc-stat-row"><button id="mc-median" class="mc-stat" aria-label="Inspect simulated median"><span><i class="mc-dot median"></i> Simulated median</span><b>${fmt(result.median)} <small>${esc(snapshot.currency)}</small></b><small>50th percentile · ${fmt(result.quantiles.p10)}–${fmt(result.quantiles.p90)} central 80%</small></button><button id="mc-market" class="mc-stat ${q.status==='ready'?'':'is-missing'}" aria-label="${q.status==='ready'?'Inspect dated market price':'Add a sourced market quote'}"><span><i class="mc-dot market"></i> ${q.status==='ready'?'Dated market price':'Market price'}</span><b>${q.status==='ready'?fmt(q.price):'Add a quote'} <small>${q.status==='ready'?esc(snapshot.currency):'↓'}</small></b><small>${q.status==='ready'?`${fmt(q.percentile,1)}th percentile · ${esc(q.date)}`:'Enter a sourced quote below to compare'}</small></button></div><p class="mc-quote-note">${q.status==='ready'?`Your entered quote: ${fmt(q.price)} ${esc(snapshot.currency)} on ${esc(q.date)} · <a href="${esc(draft.quote.sourceUrl)}" target="_blank" rel="noopener">quote source ↗</a>. ${q.price<lo||q.price>hi?'Market-price marker is pinned to the nearest chart edge. ':''}${fmt(q.percentile,1)}% of accepted simulated values are at or below that price. This is not a probability of a future market-price move.`:esc(q.message)+' No live quote feed is connected.'}</p><details class="mc-table"><summary>View exact distribution & percentile table</summary><div class="table-wrap"><table><caption>Conditional per-share values · ${esc(snapshot.currency)}</caption><thead><tr><th scope="col">Percentile</th><th scope="col">Value / share</th></tr></thead><tbody>${Object.entries(result.quantiles).map(([k,v])=>`<tr><th scope="row">${k.slice(1)}th</th><td>${fmt(v)}</td></tr>`).join('')}</tbody></table><table><caption>Histogram · all accepted scenarios</caption><thead><tr><th scope="col">Value range</th><th scope="col">Scenarios</th><th scope="col">Share</th></tr></thead><tbody>${result.histogram.map(b=>`<tr><th scope="row">${fmt(b.low)}–${fmt(b.high)}</th><td>${b.count}</td><td>${fmt(b.share*100,2)}%</td></tr>`).join('')}</tbody></table></div></details>`;
  barFinals=result.histogram.map((b,i)=>({node:root.querySelector(`[data-bin="${i}"]`),height:b.count/maxCount*(bottom-top)}));
  previousBarHeights.set(visualKey,barFinals.map(b=>b.height));
