  chart.onpointermove=e=>{if(e.pointerType==='mouse'||dragging)pointer(e)};chart.onpointerdown=e=>{dragging=true;pointer(e);try{chart.setPointerCapture?.(e.pointerId)}catch{}};chart.onpointerup=chart.onpointercancel=e=>{dragging=false;try{chart.releasePointerCapture?.(e.pointerId)}catch{}};
  chart.onkeydown=e=>{let value=selected,delta=(hi-lo)/(e.shiftKey?20:100);if(e.key==='ArrowRight'||e.key==='ArrowUp')value+=delta;else if(e.key==='ArrowLeft'||e.key==='ArrowDown')value-=delta;else if(e.key==='Home')value=lo;else if(e.key==='End')value=hi;else return;e.preventDefault();inspect(value)};
  find('#mc-skip').onclick=()=>finish();find('#mc-scrubber').oninput=e=>inspect(lo+Number(e.target.value)/1000*(hi-lo));find('#mc-median').onclick=()=>inspect(result.median,'Simulated median');find('#mc-median').onpointerenter=()=>inspect(result.median,'Simulated median');find('#mc-median').onfocus=()=>inspect(result.median,'Simulated median');find('#mc-market').onpointerenter=()=>{if(q.status==='ready')inspect(q.price,`Dated market price · ${q.date}`,true)};find('#mc-market').onfocus=()=>{if(q.status==='ready')inspect(q.price,`Dated market price · ${q.date}`,true)};find('#mc-market').onclick=()=>{if(q.status==='ready')inspect(q.price,`Dated market price · ${q.date}`,true);else{const form=document.querySelector('#market-quote');if(form){form.open=true;form.scrollIntoView({block:'start',behavior:reducedMotion()?'auto':'smooth'});document.querySelector('#quote-price')?.focus({preventScroll:true})}}};find('#mc-play').onclick=()=>{if(animations.length){if(paused){animations.forEach(a=>a.play());paused=false;find('#mc-play').textContent='Pause Ⅱ';find('#mc-play').setAttribute('aria-pressed','true')}else{animations.forEach(a=>a.pause());paused=true;find('#mc-play').textContent='Resume ▷';find('#mc-play').setAttribute('aria-pressed','false')}}else play()};
